insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('petrophysics', 'advanced', 'module', 'm01-the-rw-problem', 1, 'With Archie exponents a = 1, m = 2, n = 2, how does computed water saturation scale with the formation water resistivity Rw?', '["Linearly with Rw","As the square root of Rw","As the square of Rw","It does not depend on Rw"]'::jsonb, 1, 'Sw = sqrt(a Rw / (phi^m Rt)) for n = 2, so Sw scales as sqrt(Rw).'),
  ('petrophysics', 'advanced', 'module', 'm01-the-rw-problem', 2, 'The typewell lab sample reads 0.114 ohm.m and the corrected formation-temperature value is 0.0499 ohm.m. By what factor does using the raw value multiply every Archie Sw in the well?', '["2.28","1.18","1.51","0.66"]'::jsonb, 2, 'Sw scales as sqrt(Rw), so the factor is sqrt(0.114/0.0499) = 1.5113, even though the Rw values differ by a factor of 2.28.'),
  ('petrophysics', 'advanced', 'module', 'm01-the-rw-problem', 3, 'At the 2020 m sample (phiD 0.2100, Rt 9.2554 ohm.m), what are the Archie water saturations with the corrected Rw (0.0499) and with the raw sample value (0.114)?', '["0.3497 and 0.5285","0.3609 and 0.5303","0.2100 and 0.4324","0.3497 and 0.6498"]'::jsonb, 0, 'phi^2 Rt = 0.4082; sqrt(0.049910/0.4082) = 0.3497 and sqrt(0.114/0.4082) = 0.5285. The 0.3609/0.5303 pair are the SAND_A pay averages, not this sample.'),
  ('petrophysics', 'advanced', 'module', 'm01-the-rw-problem', 4, 'Booking SAND_A with the corrected Rw gives 18.0 m of net pay. What does the same booking give with the raw, uncorrected sample value?', '["18.0 m, because net pay is insensitive to Rw","17.5 m","19.5 m","16.5 m"]'::jsonb, 3, 'The raw 0.114 ohm.m inflates every Sw by 1.5113, pushing marginal samples past the 0.6 cutoff: net pay falls from 18.0 m to 16.5 m.'),
  ('petrophysics', 'advanced', 'module', 'm01-the-rw-problem', 5, 'Why is a booking run with an uncorrected Rw described as a quiet failure?', '["The software rejects the run and reports an error","It produces plausible-looking results with nothing to flag them as wrong","It always books zero net pay, which is easy to notice","The saturation values exceed 1 everywhere, which flags the problem"]'::jsonb, 1, 'The wrong-Rw run yields perfectly reasonable-looking saturations and pay; only independent knowledge of the correct Rw exposes the error.'),
  ('petrophysics', 'advanced', 'module', 'm01-the-rw-problem', 6, 'Which Rw route is the most direct measurement but is made ex-situ, at bench temperature?', '["The Pickett water-line fit","The SP quicklook","The laboratory measurement of a formation water sample","A regional water catalog"]'::jsonb, 2, 'The lab measures actual formation water directly, but at lab temperature and subject to contamination, so it is direct yet ex-situ.'),
  ('petrophysics', 'advanced', 'module', 'm01-the-rw-problem', 7, 'What are the two caveats that travel with a laboratory water-sample resistivity?', '["It is measured at lab temperature, and the bottle may not hold pure formation water","It only constrains the product a times Rw, and it needs a clean thick bed","It requires a shale baseline, and it fails in fresh muds","It needs a genuine water leg, and it entangles Rw with m"]'::jsonb, 0, 'The lab value needs a temperature correction to formation conditions, and the sample can be cut with mud filtrate or mixed from other aquifers. The other options describe SP and Pickett caveats.'),
  ('petrophysics', 'advanced', 'module', 'm01-the-rw-problem', 8, 'What is the key strength of the SP log as an Rw source?', '["It measures Rw with no approximations at all","It is an in-situ measurement against the water actually in the pores, with no sampling or contamination question","It separates a from Rw where the Pickett fit cannot","It works without knowing the mud filtrate resistivity"]'::jsonb, 1, 'The SP responds in-situ to the filtrate-formation water salinity contrast; its weakness is the chain of quicklook approximations, not sampling.'),
  ('petrophysics', 'advanced', 'module', 'm01-the-rw-problem', 9, 'Which limitation belongs to the Pickett-fit route to Rw?', '["It is measured at bench temperature and must be corrected with Arps","It cannot be run without a produced water sample","It requires reading a static deflection against a shale baseline","It returns a times Rw as one entangled product and requires a genuine water leg"]'::jsonb, 3, 'The water-line intercept gives the product a Rw, not Rw alone, and the fit is only as good as the water-leg identification.'),
  ('petrophysics', 'advanced', 'module', 'm01-the-rw-problem', 10, 'What is the proper role of regional water catalogs and offset-well data in an Rw study?', '["A sanity check on the measured routes, providing context rather than proof","The primary source, overriding lab and log measurements","A substitute for the temperature correction","They are only used when the three measured routes agree"]'::jsonb, 0, 'Aquifers vary laterally, so a catalog value settles nothing alone; it flags when measured, agreeing values sit outside the regional range.'),
  ('petrophysics', 'advanced', 'module', 'm01-the-rw-problem', 11, 'Why is agreement among the lab, SP and Pickett routes strong evidence for the adopted Rw?', '["Because all three routes share the same physics, so agreement is guaranteed","Because each route fails differently, and no single mistake leaves all three agreeing on the same wrong number","Because three values can be averaged to cancel random error","Because the routes are calibrated against each other before use"]'::jsonb, 1, 'The routes are independent with distinct failure modes (contamination, chain approximations, wrong water leg), so convergence is unlikely unless the number is right.'),
  ('petrophysics', 'advanced', 'module', 'm01-the-rw-problem', 12, 'What three Rw estimates does the typewell triangulation produce?', '["0.114, 0.62 and 0.05 ohm.m","0.0499, 0.0635 and 0.0873 ohm.m","0.0499, 0.0498 and 0.0500 ohm.m","0.05, 0.10 and 0.15 ohm.m"]'::jsonb, 2, 'Arps-corrected sample 0.0499, SP quicklook 0.0498 and Pickett 0.0500 ohm.m, a spread of well under one percent.'),
  ('petrophysics', 'advanced', 'module', 'm01-the-rw-problem', 13, 'Why can the lab value of 0.114 ohm.m not be used directly in the typewell saturation work?', '["It was measured on mud filtrate rather than formation water","It was measured at 75 degF while the formation is at 180 degF, and brine resistivity falls steeply with temperature","The resistivity cell only works on NaCl solutions","It is the equivalent resistivity Rwe, not the true Rw"]'::jsonb, 1, 'The sample is genuine formation water, but bench temperature is far below reservoir temperature; the Arps correction brings it to formation conditions.'),
  ('petrophysics', 'advanced', 'module', 'm01-the-rw-problem', 14, 'The Expert capstone books SAND_A with density porosity, Larionov tertiary Vsh and Archie, the Associate recipe, rather than the Professional tier''s neutron-density and shaly-sand methods. Why?', '["Because the neutron and sonic curves are unavailable at this tier","Because shaly-sand models cannot use a corrected Rw","Because the Professional booking was found to be wrong","So that only one variable, Rw, changes between runs and any movement in the answer has a single cause"]'::jsonb, 3, 'Holding the booking recipe fixed isolates the effect of Rw; the deliberate exception is the water-leg check, which uses neutron-density porosity.'),
  ('petrophysics', 'advanced', 'module', 'm01-the-rw-problem', 15, 'With the corrected Rw, the mean Archie Sw across the 2075 to 2078 m water leg is 0.9991. What does this validate?', '["That the water leg contains residual hydrocarbons","That the neutron-density porosity is biased low","That the adopted Rw reproduces known physics: a zone that must be water reads as water","That the Sw cutoff of 0.6 is set correctly"]'::jsonb, 2, 'Saturation is 1 in a water leg by definition; an adopted Rw that returns essentially unity there passes the physics check that agreement among estimates alone cannot provide.'),
  ('petrophysics', 'advanced', 'module', 'm02-temperature-and-the-arps-correction', 1, 'A lab reports formation water resistivity of 0.114 ohm.m at 75 degF. Why can this number not be used directly in Archie at reservoir conditions?', '["Lab instruments systematically overstate resistivity and a calibration factor must be applied first","Archie requires conductivity units, so the value must first be inverted","Water resistivity depends strongly on temperature, and the formation is far hotter than the lab bench","The value is only valid for mud filtrate, not formation water"]'::jsonb, 2, 'Resistivity is a property of the water at a stated temperature. The bench sits at 75 degF and the formation at 180 degF, so the value must be corrected to formation temperature before use.'),
  ('petrophysics', 'advanced', 'module', 'm02-temperature-and-the-arps-correction', 2, 'A bottom-hole temperature read from a log header shortly after circulation typically errs in which direction, and why?', '["It reads low, because the borehole has just been cooled by circulated mud","It reads high, because friction from drilling heats the borehole above formation temperature","It reads low, because maximum thermometers under-register at depth","It is unbiased, because the thermometer records the true maximum it encountered"]'::jsonb, 0, 'Circulation cools the near-wellbore, so an immediate BHT sits below true formation temperature, sometimes by 10 to 20 degC. Horner-style extrapolation over several runs corrects for this.'),
  ('petrophysics', 'advanced', 'module', 'm02-temperature-and-the-arps-correction', 3, 'What geothermal gradient is typical of sedimentary basins?', '["5 to 10 degC per km","25 to 30 degC per km","60 to 80 degC per km","100 to 120 degC per km"]'::jsonb, 1, 'Sedimentary basins typically run 25 to 30 degC per km below a surface reference temperature, which makes gradient-based estimates a useful cross-check on header temperatures.'),
  ('petrophysics', 'advanced', 'module', 'm02-temperature-and-the-arps-correction', 4, 'What happens to the resistivity of an NaCl brine as it is heated?', '["It rises, because thermal agitation scatters the charge carriers","It stays constant, because salinity does not change with temperature","It rises at first and then falls once the water begins to degas","It falls, because the water becomes less viscous and the ions drift faster"]'::jsonb, 3, 'Brine conducts by ionic transport. Heating lowers viscosity, ion mobility rises, conductivity rises, and resistivity falls. A corrected formation Rw must always be lower than its cooler lab value.'),
  ('petrophysics', 'advanced', 'module', 'm02-temperature-and-the-arps-correction', 5, 'Which physical mechanism links temperature to brine conductivity?', '["Higher temperature dissolves additional salt from the rock, adding charge carriers","Lower viscosity at higher temperature lets the dissolved ions move faster under the applied field","Thermal expansion increases the water volume and dilutes the ions","Higher temperature ionises the water molecules themselves into H+ and OH-"]'::jsonb, 1, 'The ion population is set by salinity; temperature acts on how fast those ions can drift. Thinner (hotter) water means faster drift and higher conductivity.'),
  ('petrophysics', 'advanced', 'module', 'm02-temperature-and-the-arps-correction', 6, 'Which of these is the Arps temperature correction for water resistivity, with temperatures in degF?', '["Rw2 = Rw1 x (T1 + 6.77) / (T2 + 6.77)","Rw2 = Rw1 x (T2 + 6.77) / (T1 + 6.77)","Rw2 = Rw1 x T1 / T2","Rw2 = Rw1 x (T2 - T1) / 6.77"]'::jsonb, 0, 'The offset scale (T + 6.77, degF) makes NaCl resistivity behave as an inverse proportionality, and the source temperature offset sits in the numerator so that heating lowers the result.'),
  ('petrophysics', 'advanced', 'module', 'm02-temperature-and-the-arps-correction', 7, 'Apply Arps: a sample measures 0.114 ohm.m at 75 degF and the formation is at 180 degF. What is the corrected Rw?', '["0.0475 ohm.m","0.2604 ohm.m","0.0499 ohm.m","0.1140 ohm.m"]'::jsonb, 2, '0.114 x (75 + 6.77)/(180 + 6.77) = 0.114 x 81.77/186.77 = 0.0499 ohm.m. The 0.0475 option forgets the 6.77 offsets and the 0.2604 option inverts the ratio.'),
  ('petrophysics', 'advanced', 'module', 'm02-temperature-and-the-arps-correction', 8, 'A water sample measures 0.080 ohm.m at 75 degF. What is its resistivity at 150 degF by Arps?', '["0.0522 ohm.m","0.0417 ohm.m","0.1533 ohm.m","0.0400 ohm.m"]'::jsonb, 1, '0.080 x (75 + 6.77)/(150 + 6.77) = 0.080 x 81.77/156.77 = 0.0417 ohm.m.'),
  ('petrophysics', 'advanced', 'module', 'm02-temperature-and-the-arps-correction', 9, 'A formation water has Rw = 0.050 ohm.m at 180 degF. What would the same water measure on a lab bench at 75 degF?', '["0.0219 ohm.m","0.0500 ohm.m","0.0875 ohm.m","0.1142 ohm.m"]'::jsonb, 3, 'Arps runs in both directions: 0.050 x (180 + 6.77)/(75 + 6.77) = 0.050 x 2.284 = 0.1142 ohm.m. Cooling the water raises its resistivity.'),
  ('petrophysics', 'advanced', 'module', 'm02-temperature-and-the-arps-correction', 10, 'If the Arps formula is applied with T2 equal to T1, what does it return?', '["The input resistivity unchanged, because the offset-temperature ratio is exactly 1","Zero, because there is no temperature difference to correct","The input divided by 6.77","An error, because the formula is undefined at equal temperatures"]'::jsonb, 0, 'With equal temperatures the ratio (T1 + 6.77)/(T2 + 6.77) is 1 and the resistivity passes through unchanged. This identity is a basic sanity check on any implementation.'),
  ('petrophysics', 'advanced', 'module', 'm02-temperature-and-the-arps-correction', 11, 'In what temperature unit must the Arps and SP formulas be fed, and why is this an exception in the app?', '["Kelvin, because the physics is absolute-temperature dependent","degC, because the app is SI throughout","degF, because the empirical formulas were defined on that scale; the app converts at the boundary","Either unit, because the ratio cancels the units"]'::jsonb, 2, 'The 6.77 offset was fitted on the Fahrenheit scale, so the formulas only work in degF. The engine keeps them in native form and the interface converts; the ratio does not cancel an additive offset.'),
  ('petrophysics', 'advanced', 'module', 'm02-temperature-and-the-arps-correction', 12, 'For which water type is the Arps correction calibrated?', '["Any aqueous solution regardless of composition","NaCl-dominated brines","Calcium chloride brines specifically","Fresh waters below a few hundred ppm salinity"]'::jsonb, 1, 'The 6.77 offset was fitted to sodium chloride solutions. Brines rich in other salts, and very fresh waters, depart from the behaviour and need proper salinity-based treatment.'),
  ('petrophysics', 'advanced', 'module', 'm02-temperature-and-the-arps-correction', 13, 'A water sample was diluted by mud filtrate before it reached the lab, so its bench resistivity is too high. What does the Arps correction do with this sample?', '["It partially compensates, because dilution and temperature act in opposite directions","It rejects the sample, because the formula detects inconsistent inputs","It corrects the value to the true formation Rw, because the ratio removes composition effects","It faithfully converts the wrong value to formation temperature, so the result stays wrong"]'::jsonb, 3, 'Arps moves a given water along the temperature axis only. It cannot repair a starting value that describes the wrong water; a contaminated sample stays contaminated at every temperature.'),
  ('petrophysics', 'advanced', 'module', 'm02-temperature-and-the-arps-correction', 14, 'Why does the Expert workflow cross-check the Arps-corrected sample against the SP quicklook and the Pickett fit rather than standing on the lab number alone?', '["The three routes rest on independent physics and measurements, so their agreement rules out the failure modes of any single route","The lab route is the least precise of the three and needs averaging up","Regulations require three estimates of every petrophysical parameter","The SP and Pickett routes are needed to supply the salinity input that Arps requires"]'::jsonb, 0, 'Sample contamination does not touch the SP log, and neither affects a Pickett fit read from the formation itself. Independent routes agreeing near 0.05 ohm.m is strong evidence no single failure mode is active. Arps needs no salinity input.'),
  ('petrophysics', 'advanced', 'module', 'm02-temperature-and-the-arps-correction', 15, 'A sample measures 0.30 ohm.m at 60 degF. What is its resistivity at 120 degF by Arps?', '["0.1500 ohm.m","0.5697 ohm.m","0.1580 ohm.m","0.3000 ohm.m"]'::jsonb, 2, '0.30 x (60 + 6.77)/(120 + 6.77) = 0.30 x 66.77/126.77 = 0.1580 ohm.m. The 0.1500 option uses the raw temperature ratio without the 6.77 offsets.'),
  ('petrophysics', 'advanced', 'module', 'm03-the-sp-quicklook', 1, 'The SP tool emits no signal of its own. What generates the voltage it records?', '["Electrochemical potentials arising where mud filtrate and formation water of different salinities interact","The tool''s transmitter coil inducing eddy currents in the formation","Radioactive decay of potassium in shales","The pressure differential across the mudcake, which dominates the signal"]'::jsonb, 0, 'The SP is a natural DC voltage driven by electrochemical (membrane plus liquid-junction) potentials; the electrokinetic component is minor and the tool is entirely passive.'),
  ('petrophysics', 'advanced', 'module', 'm03-the-sp-quicklook', 2, 'What is the membrane potential component of the SP?', '["A voltage generated by filtrate flowing through the mudcake under pressure","A voltage across shales, which pass cations but block anions between waters of different salinity","A voltage at the invaded-zone boundary caused by chloride''s higher mobility","A voltage produced by the casing acting as an electrode"]'::jsonb, 1, 'Negatively charged clay surfaces make shale an ion-selective membrane: cations pass, anions are blocked, and a voltage builds across the shale. The chloride-mobility effect is the separate liquid-junction component.'),
  ('petrophysics', 'advanced', 'module', 'm03-the-sp-quicklook', 3, 'A well is drilled with mud filtrate fresher than the formation water (Rmf > Rw). Against a clean permeable water sand, the SP curve will', '["hold exactly at the shale baseline","deflect positive relative to the shale baseline","deflect negative relative to the shale baseline","oscillate with no stable value"]'::jsonb, 2, 'Fresh filtrate against saltier formation water drives a negative deflection in clean permeable beds; the deflection size carries the salinity contrast.'),
  ('petrophysics', 'advanced', 'module', 'm03-the-sp-quicklook', 4, 'What exactly is the SSP that enters the quicklook equation?', '["The absolute millivolt value the curve reads in the sand","The average SP value over the whole logged interval","The deflection read in the thickest shale","The full static deflection from the shale baseline that would develop in a thick, clean, water-bearing bed"]'::jsonb, 3, 'SSP is the static SP: the full deflection between shale baseline and the clean water sand line. Absolute values mean nothing; only the difference does.'),
  ('petrophysics', 'advanced', 'module', 'm03-the-sp-quicklook', 5, 'On a log the shale baseline sits at +12 mV and the curve flattens at -81 mV against a thick clean water sand. The SSP is', '["-69 mV","-93 mV","-81 mV","+93 mV"]'::jsonb, 1, 'SSP is the clean-sand value minus the shale baseline: -81 - (+12) = -93 mV.'),
  ('petrophysics', 'advanced', 'module', 'm03-the-sp-quicklook', 6, 'Thin beds, shaliness in the sand, and hydrocarbons in the pores all affect the SP reading in the same way. Which way?', '["They shrink the deflection, biasing the derived Rwe high","They enlarge the deflection, biasing the derived Rwe low","They flip the deflection''s sign","They shift the shale baseline but leave the deflection unchanged"]'::jsonb, 0, 'All three prevent the full static deflection from developing, so the measured SSP is too small in magnitude and the computed Rwe comes out too high.'),
  ('petrophysics', 'advanced', 'module', 'm03-the-sp-quicklook', 7, 'Why should the SSP for Rw work be read in a water-bearing sand rather than in the oil zone?', '["Oil zones have no SP response at all","Water sands are always thicker","Hydrocarbons suppress the electrochemical exchange and shrink the deflection","The shale baseline cannot be drawn above an oil-water contact"]'::jsonb, 2, 'Oil and gas reduce the ionic exchange that drives the SP, so a hydrocarbon-bearing interval deflects less than the same sand water-filled; read below the contact.'),
  ('petrophysics', 'advanced', 'module', 'm03-the-sp-quicklook', 8, 'Using K = 61 + 0.133 T(degF), what is K at 140 degF?', '["74.30 mV per decade","84.94 mV per decade","79.62 mV per decade","70.98 mV per decade"]'::jsonb, 2, '0.133 x 140 = 18.62, plus 61 gives 79.62 mV per decade. The distractors are K at 100, 180 and 75 degF.'),
  ('petrophysics', 'advanced', 'module', 'm03-the-sp-quicklook', 9, 'At 180 degF (K = 84.94), a carefully read SSP of about -85 mV tells you, before any further arithmetic, that', '["Rwe is about one tenth of Rmfe","Rwe is about equal to Rmfe","Rwe is about ten times Rmfe","Rwe is about half of Rmfe"]'::jsonb, 0, 'One K of millivolts is one decade of contrast: SSP/K is about -1, so Rwe = Rmfe x 10^(-1), one tenth of the filtrate value.'),
  ('petrophysics', 'advanced', 'module', 'm03-the-sp-quicklook', 10, 'With SSP = -93 mV, K = 84.94 and Rmfe = 0.62 ohm.m, the quicklook Rwe is', '["0.062 ohm.m","0.0873 ohm.m","0.1219 ohm.m","0.0498 ohm.m"]'::jsonb, 3, 'SSP/K = -93/84.94 = -1.0949; 10^(-1.0949) = 0.0804; 0.62 x 0.0804 = 0.0498 ohm.m. This is the typewell capstone value.'),
  ('petrophysics', 'advanced', 'module', 'm03-the-sp-quicklook', 11, 'Repeating the typewell arithmetic with a misread SSP of -60 mV instead of -93 mV (K = 84.94, Rmfe = 0.62) gives Rwe = 0.1219 ohm.m instead of 0.0498. What does this demonstrate?', '["The equation is linear in SSP, so errors propagate proportionally","Rwe depends exponentially on SSP, so a 33 mV misread moved the answer by a factor of about 2.4","K should have been evaluated at 75 degF","The misread changes Rwe by less than the capstone tolerance"]'::jsonb, 1, 'SSP sits in the exponent, so millivolt errors amplify exponentially: 0.1219/0.0498 is a factor of about 2.4, far outside any tolerance.'),
  ('petrophysics', 'advanced', 'module', 'm03-the-sp-quicklook', 12, 'At which temperature must K be evaluated, and why?', '["Surface temperature, because that is where the reference electrode sits","Laboratory temperature, to match the water sample measurement","Formation temperature, because that is where the electrochemical potential is generated","Any temperature, because K cancels out of the rearranged equation"]'::jsonb, 2, 'The SP is generated downhole at formation temperature, so K (and Rmfe) must be taken at that temperature; the typewell uses K(180) = 84.94.'),
  ('petrophysics', 'advanced', 'module', 'm03-the-sp-quicklook', 13, 'The engine''s SP chain treats Rmfe as approximately Rmf and the computed Rwe as approximately Rw, and does NOT implement the full Bateman and Konen (1977) conversions. Why not?', '["The conversions only apply to oil-based muds","The conversions are numerically unstable","They would make the quicklook slower than the Arps route","The coefficients will only be added once a page-referenced source is available to validate against, rather than guessed"]'::jsonb, 3, 'It is a documented quicklook approximation: the platform''s validation-first rule prefers a stated omission over an unverified implementation. The approximation is good for moderately saline NaCl waters.'),
  ('petrophysics', 'advanced', 'module', 'm03-the-sp-quicklook', 14, 'On the typewell, the SP route gives Rwe = 0.049831 ohm.m and the Arps-corrected laboratory sample gives 0.049910 ohm.m. The best characterisation of this result is:', '["Two independent physical routes agree within about 0.0001 ohm.m, so the value is strongly corroborated","The two values disagree by more than the capstone tolerance, so one route must be discarded","The agreement is expected because both routes share the same input data","The SP value should be averaged with the sample value and the average booked"]'::jsonb, 0, 'The routes share no data (a water sample and a thermometer versus log millivolts and the mud report), so their 0.2 percent agreement is genuine independent confirmation.'),
  ('petrophysics', 'advanced', 'module', 'm03-the-sp-quicklook', 15, 'A carefully read SSP comes out POSITIVE in a clean water sand. What does this indicate?', '["A wiring fault: SSP can never be positive","The formation water is fresher than the mud filtrate (Rwe greater than Rmfe)","The bed is too thin to read","The formation is hydrocarbon bearing"]'::jsonb, 1, 'A positive deflection means the salinity contrast is reversed: filtrate saltier than formation water. The equation still applies with the sign carried through, though an unexpected positive SSP in a salty-water basin should first prompt a baseline check.'),
  ('petrophysics', 'advanced', 'module', 'm04-triangulation-and-validation', 1, 'The typewell''s three Rw routes give 0.049910 (Arps lab), 0.049831 (SP quicklook) and 0.0500 (Pickett) ohm.m. How large is the spread from lowest to highest, relative to the value?', '["About 4 percent, marginal agreement","About 10 percent, requiring a documented range","Under 0.4 percent, agreement for every practical purpose","Exactly zero, the routes are mathematically identical"]'::jsonb, 2, 'The range is 0.000169 ohm.m, which is about 0.34 percent of the value, so the triangle closes convincingly.'),
  ('petrophysics', 'advanced', 'module', 'm04-triangulation-and-validation', 2, 'Why is the agreement of the laboratory, SP and Pickett routes strong evidence that the common value is correct?', '["The three routes have disjoint failure modes, so landing on the same wrong answer would require unrelated errors to conspire","Each route uses the same Archie parameters, so consistency is guaranteed","Three measurements always average out random noise","The laboratory route calibrates the other two before they are computed"]'::jsonb, 0, 'No failure mode appears on more than one route''s list; contamination, SSP suppression and leg quality are unrelated, so a closed triangle is very unlikely to be a common error.'),
  ('petrophysics', 'advanced', 'module', 'm04-triangulation-and-validation', 3, 'What does the Pickett route actually report as its Rw vertex of the triangle?', '["Rw directly, with no assumptions","The product a times Rw from the fitted intercept, read as Rw when a equals 1","The ratio of Rw to Rmfe","The cementation exponent m converted to a resistivity"]'::jsonb, 1, 'The Pickett intercept delivers the product aRw; a and Rw remain entangled, and only with a = 1 does the product read directly as Rw.'),
  ('petrophysics', 'advanced', 'module', 'm04-triangulation-and-validation', 4, 'The laboratory route reads clearly HIGH while the SP and Pickett routes agree on a lower value. Which failure should you suspect first?', '["A shale baseline drift on the SP log","An invaded water leg biasing the Pickett fit","A wrong cementation exponent in the Archie parameter set","Sample contamination by fresher mud filtrate, or a wrongly recorded sample temperature"]'::jsonb, 3, 'Filtrate from a fresher mud raises the measured sample resistivity, and a wrong measurement temperature corrupts the Arps anchor; both displace only the laboratory route, matching the pattern.'),
  ('petrophysics', 'advanced', 'module', 'm04-triangulation-and-validation', 5, 'The SP route stands apart from agreeing lab and Pickett routes. Which pair of suspects fits that pattern?', '["A misread SSP (thin bed, suppression, baseline drift) or a wrong Rmfe","Sample evaporation or precipitation before the laboratory measurement","A water leg that is not truly at Sw = 1","An incorrect matrix density in the porosity calculation"]'::jsonb, 0, 'SSP reading errors and Rmfe errors live entirely inside the SP chain and leave the other two routes untouched.'),
  ('petrophysics', 'advanced', 'module', 'm04-triangulation-and-validation', 6, 'Two routes agree and one stands apart. Why is adopting the majority value immediately a mistake?', '["The outlier is statistically more likely to be correct","Majority values must always be averaged with the outlier","The agreeing pair must first survive a review of their own failure modes, since two routes can agree for unrelated bad reasons","Triangulation requires at least four routes before any value can be adopted"]'::jsonb, 2, 'A suppressed SSP and a hydrocarbon-tainted water leg can push their estimates the same way; two-against-one is a starting heuristic, and the pair''s reliability must be checked before their agreement counts.'),
  ('petrophysics', 'advanced', 'module', 'm04-triangulation-and-validation', 7, 'After full review, the three routes still cannot be reconciled. What is the professional course of action?', '["Adopt the Pickett value because it comes from the logs themselves","Report a documented range, book the reservoir at both ends as an explicit sensitivity, and state what new data would settle it","Average the three values and proceed with the mean","Postpone the evaluation until a fourth route becomes available"]'::jsonb, 1, 'An open triangle is carried as a documented range with its booking consequences shown, never resolved by a silent pick or a blind average.'),
  ('petrophysics', 'advanced', 'module', 'm04-triangulation-and-validation', 8, 'What should Archie return across a true water leg when run with the correct parameter set?', '["Saturations rising steadily with depth","Saturations near the Sw cutoff of 0.6","Saturations of exactly zero","Saturations clustered tightly at 1 within measurement noise"]'::jsonb, 3, 'The leg is at Sw = 1 by interpretation, so a validated parameter set must reproduce unity across it; drift or scatter indicts the parameters or the leg.'),
  ('petrophysics', 'advanced', 'module', 'm04-triangulation-and-validation', 9, 'With the Arps-corrected Rw of 0.049910 ohm.m, the typewell water leg returns Sw = 0.99910 at every sample. Why do the values sit just below 1 rather than on it?', '["Because sqrt(0.049910/0.0500) = 0.99910: the tiny deficit is exactly the difference between the adopted Rw and the 0.0500 the leg itself implies","Because the neutron-density porosity is biased low in water","Because Archie systematically underestimates saturation in clean sands","Because the engine subtracts a fixed calibration margin from computed saturations"]'::jsonb, 0, 'Sw scales as the square root of Rw, and the adopted 0.049910 is slightly below the leg-implied 0.0500, so every sample reads 0.99910; the imperfection is fully explained arithmetic, not error.'),
  ('petrophysics', 'advanced', 'module', 'm04-triangulation-and-validation', 10, 'Why does the engine deliberately NOT clamp computed water saturations at 1?', '["Clamping would slow the computation over long intervals","Values above 1 are averaged out later in zone summaries","Sw greater than 1 is information: it flags wrong parameters or bad data, and clamping would hide that alarm","The convention only applies to shaly-sand models, not Archie"]'::jsonb, 2, 'A clamped water leg would look well behaved even with a badly wrong Rw; the impossible value is the diagnostic, and hiding it would let the error reach the booking.'),
  ('petrophysics', 'advanced', 'module', 'm04-triangulation-and-validation', 11, 'Running the water-leg sample at 2076 m with the RAW laboratory value of 0.114 ohm.m instead of the corrected Rw returns which saturation?', '["0.9991, unchanged from the corrected run","1.5100, an impossible value that flags the uncorrected Rw","0.6614, just above the saturation cutoff","Exactly 1.0000 after the engine normalises the leg"]'::jsonb, 1, 'The scaling factor is sqrt(0.114/0.049910) = 1.5113, and 0.99910 times 1.5113 = 1.5100; the water leg announces the error before it corrupts any booking.'),
  ('petrophysics', 'advanced', 'module', 'm04-triangulation-and-validation', 12, 'A sample reads Sw = 0.80 with Rw = 0.05 ohm.m. Using the scaling rule, what does the same sample read with Rw = 0.02 ohm.m?', '["0.32, scaling linearly with Rw","0.80, since Rw does not enter Archie","1.26, scaling with the inverse square root","About 0.51, from 0.80 times sqrt(0.02/0.05)"]'::jsonb, 3, 'Sw2 = Sw1 sqrt(Rw2/Rw1) = 0.80 x sqrt(0.4) = 0.80 x 0.632 = 0.506, about 0.51; the rule converts any Archie saturation between candidate Rw values without recomputing from the logs.'),
  ('petrophysics', 'advanced', 'module', 'm04-triangulation-and-validation', 13, 'Which four elements make up a complete adoption statement for a parameter such as Rw?', '["The value, its provenance, its uncertainty, and its domain of validity","The value, the analyst''s name, the software version, and the date","The mean, the median, the mode, and the standard deviation of the routes","The value, the water-leg depths, the mud type, and the logging contractor"]'::jsonb, 0, 'A value without provenance is an assertion, provenance without uncertainty invites false precision, and without a domain statement the value will one day be applied to a reservoir it does not describe.'),
  ('petrophysics', 'advanced', 'module', 'm04-triangulation-and-validation', 14, 'Adopting the rounded Rw = 0.05 instead of the computed 0.049910 was judged defensible on the typewell. On what basis?', '["Round values are preferred by convention in all reports","The Pickett route already reported 0.0500, so rounding restores the majority value","The cost was measured and shown immaterial: SAND_A pay-average Sw moves only from 0.3609 to 0.3613 and net pay stays 18.0 m","The laboratory tolerance of 0.0005 makes the third decimal meaningless"]'::jsonb, 2, 'Rounding is defensible only when its effect on the numbers that matter is computed, recorded and shown to be immaterial; here saturation moves 0.0004 and no pay moves at all.'),
  ('petrophysics', 'advanced', 'module', 'm04-triangulation-and-validation', 15, 'A produced-water analysis arrives a year after the evaluation was issued. What does the Expert standard require?', '["Ignore it unless it differs from the adopted value by more than 10 percent","Re-run the triangulation with the new vertex, re-validate in the water leg, re-book if the adopted value changes, and issue a versioned revision of the report","Replace the laboratory vertex in the original report and update its figures in place","Treat it as unreliable because it postdates the logging campaign"]'::jsonb, 1, 'Produced water outranks the pre-production bottle, but the change goes through the full loop and a versioned revision; silent in-place edits destroy the audit trail the adoption statement exists to create.'),
  ('petrophysics', 'advanced', 'module', 'm05-rw-sensitivity-and-booking', 1, 'The Expert booking of SAND_A deliberately reuses the Associate recipe (density porosity, Larionov tertiary Vsh, Archie, standard cutoffs) and changes only Rw. Why?', '["The Professional methods are not licensed at the Expert tier","So that every difference between the two bookings is attributable to the single changed parameter","Because density porosity is always more accurate than neutron-density","Because Archie is the only model that accepts a corrected Rw"]'::jsonb, 1, 'Holding porosity source, Vsh transform and cutoffs fixed is an experimental control: with one input moved, the change in the answer measures that input''s effect.'),
  ('petrophysics', 'advanced', 'module', 'm05-rw-sensitivity-and-booking', 2, 'Booked with the corrected Rw of 0.049910 ohm.m, SAND_A reports which of the following?', '["Net 16.5 m, NTG 0.805, pay-average Sw 0.5303","Net 18.0 m, NTG 0.878, pay-average Sw 0.3609","Net 20.5 m, NTG 1.000, pay-average Sw 0.3497","Net 5.5 m, NTG 0.180, pay-average Sw 0.5418"]'::jsonb, 1, 'The corrected booking gives gross 20.5 m, net 18.0 m, NTG 0.878, pay-average porosity 0.2081 and pay-average Sw 0.3609. The 16.5 m set is the raw-sample booking and the 5.5 m set is SAND_B.'),
  ('petrophysics', 'advanced', 'module', 'm05-rw-sensitivity-and-booking', 3, 'The corrected-Rw booking of SAND_A returns essentially the same numbers as the Associate booking that assumed Rw = 0.05. What is the correct reading of this outcome?', '["The validation succeeded: the assumed parameter is now a proven one, so the booking is defensible","The Expert work was redundant and should have been skipped","The agreement is coincidental and both bookings are suspect","The Associate booking must be revised downward to remain conservative"]'::jsonb, 0, 'A validation that confirms the existing answer is a success: the number did not change, but it stopped being an assumption and became a conclusion.'),
  ('petrophysics', 'advanced', 'module', 'm05-rw-sensitivity-and-booking', 4, 'At 2020 m the sample has phiD 0.2100 and Rt 9.2554 ohm.m. With the corrected Rw of 0.049910 ohm.m, Archie (a=1, m=n=2) gives approximately:', '["Sw = 0.53","Sw = 0.60","Sw = 0.35","Sw = 0.12"]'::jsonb, 2, '0.2100 squared is 0.0441; 0.0441 x 9.2554 = 0.4082; 0.049910/0.4082 = 0.1223; the square root is 0.3497. 0.53 is the raw-Rw value and 0.12 is the ratio before the square root.'),
  ('petrophysics', 'advanced', 'module', 'm05-rw-sensitivity-and-booking', 5, 'Booking SAND_A with the uncorrected lab value of 0.114 ohm.m changes the summary how?', '["Net rises to 20.5 m because more samples pass the cutoffs","Net falls to 16.5 m and pay-average Sw rises to 0.5303","Net is unchanged but pay-average Sw falls to 0.3497","Only the pay-average porosity changes"]'::jsonb, 1, 'The raw Rw inflates every Sw by 1.5113, pushing 1.5 m of pay over the 0.6 cutoff: net 16.5 m, NTG 0.805, pay-average Sw 0.5303.'),
  ('petrophysics', 'advanced', 'module', 'm05-rw-sensitivity-and-booking', 6, 'Physically, why does using the 75 degF bench resistivity at a 180 degF formation inflate every computed water saturation?', '["Hot brine conducts much better than bench brine, so the bench value overstates Rw and Archie needs more water to explain the observed Rt","The density log reads differently at formation temperature","Archie''s exponent m increases with temperature","The lab sample evaporates and concentrates its salt before measurement"]'::jsonb, 0, 'Ionic mobility rises with temperature, so true formation Rw is far lower than the bench value. Telling Archie the water is a poorer conductor forces it to explain the measured Rt with a higher water fraction.'),
  ('petrophysics', 'advanced', 'module', 'm05-rw-sensitivity-and-booking', 7, 'For n = 2, replacing the corrected Rw (0.049910) with the raw sample value (0.114) multiplies every Archie saturation in the well by:', '["0.114/0.049910 = 2.284","sqrt(0.114/0.049910) = 1.511","sqrt(0.049910/0.114) = 0.662","It changes each sample by a different factor depending on porosity"]'::jsonb, 1, 'Sw scales with the square root of (a Rw), so the ratio is sqrt(0.114/0.049910) = 1.5113, identical at every sample because Rw is a shared parameter.'),
  ('petrophysics', 'advanced', 'module', 'm05-rw-sensitivity-and-booking', 8, 'With a saturation scaling factor of 1.5113 and a pay cutoff of Sw = 0.6, which samples flip from pay to non-pay under the wrong Rw?', '["Samples with corrected Sw between 0.397 and 0.600","Samples with corrected Sw below 0.397","Samples with corrected Sw above 0.600","All pay samples flip regardless of saturation"]'::jsonb, 0, 'A sample survives the raw booking only if its corrected Sw is at or below 0.6/1.5113 = 0.397. The flip band is therefore 0.397 to 0.600; below it samples are safe, above it they were never pay.'),
  ('petrophysics', 'advanced', 'module', 'm05-rw-sensitivity-and-booking', 9, 'SAND_A lost exactly 1.5 m of net between the two bookings. At the typewell''s 0.5 m sampling this corresponds to:', '["One sample at the crest of the sand","Three samples near the edges of the sand where saturation climbs toward the cutoff","Every second sample across the zone","The three highest-porosity samples in the zone"]'::jsonb, 1, 'Three 0.5 m samples fell inside the 0.397-0.600 flip band. They sit at the zone''s edges, where saturation rises away from the mid-sand values near 0.35.'),
  ('petrophysics', 'advanced', 'module', 'm05-rw-sensitivity-and-booking', 10, 'Pay-average porosity ROSE from 0.2081 to 0.2099 in the raw-Rw booking that lost 1.5 m of pay. Why?', '["The raw Rw increases computed porosity slightly","Rounding error in the zone summary","The flipped samples were poorer rock, so the surviving sample set averages higher; conditional averages move with their sample set","The engine re-normalises porosity to the smaller net"]'::jsonb, 2, 'No porosity value changed; the membership of the average did. Removing the poorer edge samples raised the mean of the survivors, which is why pay averages must always be read together with net.'),
  ('petrophysics', 'advanced', 'module', 'm05-rw-sensitivity-and-booking', 11, 'Booked with the corrected Rw, SAND_B (2050-2080 m) reports gross 30.5 m and:', '["Net 18.0 m, NTG 0.878, pay-average Sw 0.3609","Net 11.0 m, NTG 0.361, pay-average Sw 0.4500","Net 2.0 m, NTG 0.066, pay-average Sw 0.5900","Net 5.5 m, NTG 0.180, pay-average porosity 0.1417, pay-average Sw 0.5418"]'::jsonb, 3, 'SAND_B is a thin oil fringe over the water leg: 5.5 m of net from 30.5 m gross, poorer rock (0.1417) and wetter pay (0.5418) than SAND_A.'),
  ('petrophysics', 'advanced', 'module', 'm05-rw-sensitivity-and-booking', 12, 'Why is SAND_B''s booking far more fragile to an Rw error than SAND_A''s?', '["Its gross interval is thicker, so more samples are exposed","Most of its surviving pay carries saturations near the 0.6 cutoff, inside the flip band a plausible Rw error creates","Its porosity is too low for Archie to apply","The water leg at its base makes the resistivity log unreliable there"]'::jsonb, 1, 'SAND_A''s pay is anchored around Sw 0.35, below the flip band. SAND_B''s pay crowds the cutoff from below, so the same scaling factor pushes nearly all of it over the line.'),
  ('petrophysics', 'advanced', 'module', 'm05-rw-sensitivity-and-booking', 13, 'Which statement best captures the field view the module recommends?', '["SAND_B should be booked at zero net until an appraisal well is drilled","Both sands should be reported with the raw-sample Rw as a conservative case","SAND_A is the robust, bankable asset; SAND_B is marginal upside whose booked value depends directly on parameter quality, so validation effort matters most there","Sensitivity effort should be allocated in proportion to each zone''s booked volume"]'::jsonb, 2, 'Marginal zones with saturations crowding the cutoffs are where cutoff arithmetic amplifies parameter error, so they need the validation effort more than the robust volume-carrying zone does.'),
  ('petrophysics', 'advanced', 'module', 'm05-rw-sensitivity-and-booking', 14, 'The report states the sensitivity delta in hydrocarbon pore thickness: 2.393 hydrocarbon-metres for the adopted booking versus 1.626 for the raw one. Why is this preferred over quoting the net-pay change alone?', '["Hydrocarbon-metres is the unit the drilling department uses","Net pay cannot be computed for the raw booking","It avoids disclosing the saturation values","Net alone understates the swing (8 percent) because saturation moved too; the product net x porosity x hydrocarbon saturation shows the true 32 percent loss that feeds volumetrics"]'::jsonb, 3, 'h_hc = h_net x phi_avg x (1 - Sw_avg) compounds both effects: 18.0 x 0.2081 x 0.6391 = 2.393 versus 16.5 x 0.2099 x 0.4697 = 1.626, a 32 percent swing that the net-pay line alone hides.'),
  ('petrophysics', 'advanced', 'module', 'm05-rw-sensitivity-and-booking', 15, 'A revised Rw arrives after the report is issued. The module''s governing rule is:', '["Re-book the zones from the recipe and version the report; never scale the old averages, because the cutoff re-flags samples and every conditional average moves with its new sample set","Multiply the reported saturations by the square-root factor and update the summary lines","Keep the original booking unchanged for audit consistency","Adjust only the water-leg check and leave the zone tables as issued"]'::jsonb, 0, 'Scaling old averages produces numbers corresponding to no booking at all: membership of the net changes with the cutoff. The recipe is cheap to rerun, so rerun it and keep the superseded booking in an appendix.'),
  ('petrophysics', 'advanced', 'module', 'm06-the-expert-standard', 1, 'What is the unifying principle that connects the Associate, Professional and Expert tiers of the petrophysics ladder?', '["Each tier converts one more assumption into evidence","Each tier replaces the previous tier''s equations with more accurate ones","Each tier works on a different dataset of increasing difficulty","Each tier reduces the number of parameters the workflow needs"]'::jsonb, 0, 'The tiers keep the same loop and dataset; what deepens is the evidence standard. Associate runs the loop on givens, Professional validates methods and fits parameters, Expert earns the parameters by triangulation.'),
  ('petrophysics', 'advanced', 'module', 'm06-the-expert-standard', 2, 'On the provenance ladder, what distinguishes a triangulated parameter from a fitted one?', '["A triangulated parameter is always quoted with more decimal places","A fitted parameter comes from core data while a triangulated one comes from logs","Independent measurements with no common failure mode converge on a triangulated value, while a fitted value comes from one dataset","A triangulated parameter is averaged from three arbitrary guesses"]'::jsonb, 2, 'Fitted means the data in front of you produced it (like the Pickett fit); triangulated means independent routes, such as Arps, SP and Pickett, converge on it, which is the strongest rung because the routes share no common failure mode.'),
  ('petrophysics', 'advanced', 'module', 'm06-the-expert-standard', 3, 'Why is writing ''Rw = 0.05 ohm.m (triangulated: Arps, SP, Pickett)'' a different scientific claim from writing ''Rw = 0.05 ohm.m'' alone?', '["The first form implies the value was measured in a laboratory","The first form states the evidence behind the number, so the reader knows which rung of the provenance ladder it sits on","The second form is numerically less precise","The first form is required by regulators for all reports"]'::jsonb, 1, 'The number is identical; the provenance statement is what changes the claim. Stating the rung is part of stating the number.'),
  ('petrophysics', 'advanced', 'module', 'm06-the-expert-standard', 4, 'The three Rw routes on the typewell span roughly 0.4 percent. What role does that spread play in the Expert report?', '["It is an error that should be eliminated before reporting","It shows the SP route is unreliable and should be discarded","It proves the water leg was picked incorrectly","It is the uncertainty statement attached to the adopted Rw"]'::jsonb, 3, 'The spread between independent routes is the honest uncertainty statement. On the typewell it is small by design; in field data a larger spread is common and reporting it lets the next user judge whether it matters.'),
  ('petrophysics', 'advanced', 'module', 'm06-the-expert-standard', 5, 'The capstone grades each of its six numbers within a tolerance band rather than demanding exact values. What principle does that reflect?', '["The engine cannot compute exact answers","Tolerances make uncertainty operational: an answer is the same answer within a stated band","The grader rounds all submissions to two decimal places","Tolerances exist only to forgive typing mistakes"]'::jsonb, 1, 'Tolerances are uncertainty made operational. A grader, like a partner or regulator, needs the band within which your answer is unchanged, not just the value.'),
  ('petrophysics', 'advanced', 'module', 'm06-the-expert-standard', 6, 'Why does the 18.0 m versus 16.5 m booking pair do more work in a report than a paragraph stating that Rw is important?', '["It demonstrates the consequence: it proves the parameter matters, quantifies how much, and shows the direction of the error","It shows the software was run twice, which doubles confidence","Net pay is the only number managers read","It replaces the need to state any uncertainty on Rw"]'::jsonb, 0, 'A sensitivity demonstration is evidence of consequence. The pair quantifies exactly what the uncorrected parameter does to booked pay: 1.5 m.'),
  ('petrophysics', 'advanced', 'module', 'm06-the-expert-standard', 7, 'What is the operational test of a defensible evaluation?', '["It uses the most advanced saturation model available","It was reviewed by at least two managers before release","Another expert, given the report and the data, reproduces the numbers and finds no unexamined assumption doing load-bearing work","Its saturations are quoted to at least four decimal places"]'::jsonb, 2, 'Defensible means reproducible with every load-bearing choice documented, its provenance stated and its consequence quantified. Disagreement can still happen, but it happens in the open about stated evidence.'),
  ('petrophysics', 'advanced', 'module', 'm06-the-expert-standard', 8, 'Quoting Sw = 0.3609 while Rw rests on a single uncorrected lab measurement is an example of what failure?', '["Under-reporting, because more decimals should be shown","False precision: the display precision claims a certainty the provenance cannot support","Conservatism, because the value is biased high","A rounding error in the fourth decimal place"]'::jsonb, 1, 'Precision belongs to the arithmetic; certainty belongs to the evidence. An uncorrected sample shifts every saturation by a factor of about 1.51, so four displayed decimals would be meaningless.'),
  ('petrophysics', 'advanced', 'module', 'm06-the-expert-standard', 9, 'Which six quantities does the Expert capstone grade?', '["Gross, net, NTG, mean porosity, mean Vsh and mean Sw for SAND_A","Three porosity means, the Pickett a*Rw and m, and one saturation mean","Rw by Arps and by Pickett, plus net pay for SAND_A and SAND_B with each","Arps Rw, SP quicklook Rwe, water-leg mean Sw, SAND_A net pay and pay-average Sw with the corrected Rw, and SAND_A net pay with the raw sample value"]'::jsonb, 3, 'Two parameter routes, one validation, and the corrected booking pair (net and pay-average Sw) plus the uncorrected net: the whole course in six numbers.'),
  ('petrophysics', 'advanced', 'module', 'm06-the-expert-standard', 10, 'In what order does the deep path unlock its assessments?', '["Final exam first, then module quizzes, then the capstone","Read a module''s lessons to unlock its quiz, pass every module quiz, pass the final exam, then the capstone unlocks","The capstone may be attempted at any time; quizzes are optional practice","Module quizzes and the final exam can be taken in any order before the capstone"]'::jsonb, 1, 'The order is enforced server-side: lessons unlock the module quiz, all module quizzes precede the final exam, and the capstone is the last door.'),
  ('petrophysics', 'advanced', 'module', 'm06-the-expert-standard', 11, 'What are the pass thresholds on the deep path, and what happens after three failed quiz attempts?', '["80 percent for quizzes and exam alike, with no retake limit","70 percent for module quizzes, 75 percent for the final exam, with a 12 hour cooldown","75 percent for module quizzes and 70 percent for the final exam, with a 24 hour cooldown after three failed quiz attempts","60 percent for both, with a permanent lock after three failures"]'::jsonb, 2, 'Module quizzes pass at 75 percent, the final exam at 70 percent, and three failed attempts trigger a 24 hour cooldown, which rewards reading before guessing.'),
  ('petrophysics', 'advanced', 'module', 'm06-the-expert-standard', 12, 'Besides the certification itself, what does passing the Expert capstone automatically issue?', '["A personal single-use 50 percent discount code for the corresponding Petrolord Suite module, valid for the certificate''s twelve-month window","Free enrollment in the next course on the geoscience path","A permanent license for the Petrophysics app","An extension of the certificate''s validity to twenty-four months"]'::jsonb, 0, 'The Expert tier carries a commercial rider: the certification auto-issues a single-use 50 percent Suite discount code tied to the certificate''s twelve-month validity.'),
  ('petrophysics', 'advanced', 'module', 'm06-the-expert-standard', 13, 'Why does the typewell deliberately hold hole conditions ideal?', '["Because the engine cannot model washouts or gas effects","So the course can be completed in less time","Because real wells with good hole conditions are the most common case","So the parameter reasoning stays visible instead of being buried under data complications"]'::jsonb, 3, 'The teaching bet of the ladder: learn the reasoning skeleton clean first, then add the noise. Field complications are real but they obscure exactly the logic being taught.'),
  ('petrophysics', 'advanced', 'module', 'm06-the-expert-standard', 14, 'Where core-plug measurements of m, n and saturation exist, how should they rank against the transforms taught in this ladder?', '["They should be averaged with the log-based estimates","Core outranks every transform in this course","They are only a quality check and never change the booking","They rank below the Pickett fit because core is a point measurement"]'::jsonb, 1, 'Direct laboratory measurement on reservoir rock is the strongest evidence available; where core exists it outranks the log-based defaults and transforms.'),
  ('petrophysics', 'advanced', 'module', 'm06-the-expert-standard', 15, 'Which of the following transfers unchanged from the typewell to real field studies?', '["The specific values Rw = 0.05 ohm.m and m = 2.0","The assumption that a water leg is always present at the base of the deepest sand","The triangulate-validate-stress-test discipline and the provenance ladder","The exact six numbers of the Expert capstone"]'::jsonb, 2, 'Values and datasets change well to well; the disciplines do not: seek independent routes, validate where the answer is known, quantify what the parameter does to the booking, and state provenance.'),
  ('petrophysics', 'advanced', 'final', null, 1, 'In Archie''s equation with n = 2, water saturation is proportional to the square root of a*Rw. Why does this make Rw the single most damaging parameter to get wrong in a clean-sand evaluation?', '["Because Rw appears twice in the equation, once in the numerator and once in the exponent","Because porosity and Vsh errors are always negligible in clean sands","Because every computed Sw in the well scales by the same factor when Rw is wrong, and the Sw cutoff then converts that smooth shift into discrete lost or gained pay","Because Rw is the only parameter that cannot be measured in a laboratory"]'::jsonb, 2, 'A wrong Rw multiplies every Sw by sqrt(Rw_wrong/Rw_true), and samples near the Sw cutoff flip sides, moving booked net pay.'),
  ('petrophysics', 'advanced', 'final', null, 2, 'The typewell lab sample reads 0.114 ohm.m but the corrected formation-temperature value is 0.049910 ohm.m. By what factor does every Archie Sw (n = 2) inflate if the raw value is used instead of the corrected one?', '["sqrt(0.114/0.049910), which is about 1.51","0.114/0.049910, which is about 2.28","(0.114/0.049910) squared, which is about 5.22","log10(0.114/0.049910), which is about 0.36"]'::jsonb, 0, 'Sw is proportional to sqrt(a*Rw) for n = 2, so the inflation factor is sqrt(0.114/0.049910) = 1.5113.'),
  ('petrophysics', 'advanced', 'final', null, 3, 'The Expert workflow insists on three routes to Rw (lab sample with Arps, SP quicklook, Pickett fit). What makes agreement between them strong evidence rather than redundancy?', '["All three routes share the same inputs, so agreement confirms the inputs were entered correctly","The routes fail in different ways (contamination, SSP misreads, wrong water-leg identification), so a common answer is very unlikely to be a common error","Three values allow a statistical average with a formal confidence interval","Regulations require at least three independent estimates before booking reserves"]'::jsonb, 1, 'Independence is the point: each route has different failure modes, so convergence is unlikely to happen by coincidence.'),
  ('petrophysics', 'advanced', 'final', null, 4, 'Why can the typewell''s lab water resistivity of 0.114 ohm.m not be used directly in the saturation equations?', '["Because laboratory resistivity meters read equivalent rather than true resistivity","Because the sample was measured on a NaCl scale and the formation brine is not NaCl","Because 0.114 ohm.m is outside the valid range of the Archie equation","Because it was measured at 75 degF while the formation sits at 180 degF, and brine resistivity falls strongly with temperature"]'::jsonb, 3, 'Resistivity is temperature dependent; the bench value must be corrected to formation temperature (Arps) before use.'),
  ('petrophysics', 'advanced', 'final', null, 5, 'At 2020 m the typewell reads density porosity 0.2100 and RT 9.2554 ohm.m. With a = 1, m = n = 2 and the corrected Rw of 0.049910 ohm.m, what is the Archie water saturation?', '["About 0.53","About 0.35","About 0.21","About 0.46"]'::jsonb, 1, 'Sw = sqrt(0.049910/(0.2100^2 x 9.2554)) = 0.3497. The 0.53 distractor is what the raw uncorrected Rw would give.'),
  ('petrophysics', 'advanced', 'final', null, 6, 'Which of the three Rw routes in the Expert workflow are in-situ measurements of the formation itself?', '["The lab sample and the SP quicklook","The lab sample only","The SP quicklook and the Pickett water-leg fit","All three routes are in-situ"]'::jsonb, 2, 'SP and Pickett read the formation downhole; the lab sample is a surface measurement of produced or sampled water.'),
  ('petrophysics', 'advanced', 'final', null, 7, 'Which order correctly states the Expert workflow on the typewell?', '["Correct the lab sample with Arps, convert the SSP reading, compare both with the Pickett fit, validate in the water leg, then book SAND_A with the corrected Rw and once more with the raw value","Book SAND_A first, then find the Rw that reproduces the booking, then check it against the lab sample","Fit the Pickett line, force the lab sample to match it, then skip the water-leg check since Pickett used the water leg already","Convert the SSP reading, average it with the raw lab value, and book with the average"]'::jsonb, 0, 'Triangulate the three routes, validate the adopted value in the water leg, then book and stress-test the booking.'),
  ('petrophysics', 'advanced', 'final', null, 8, 'Apply the Arps correction Rw2 = Rw1 x (T1 + 6.77)/(T2 + 6.77) to the typewell sample: 0.114 ohm.m at 75 degF, formation temperature 180 degF.', '["0.114 x 186.77/81.77 = 0.260 ohm.m","0.114 x 180/75 = 0.274 ohm.m","0.114 x 75/180 = 0.048 ohm.m","0.114 x 81.77/186.77 = 0.0499 ohm.m"]'::jsonb, 3, 'The offset temperatures are 81.77 and 186.77; the ratio 0.437811 gives 0.049910 ohm.m. The first distractor inverts the ratio; the others drop the 6.77 offset.'),
  ('petrophysics', 'advanced', 'final', null, 9, 'The same 0.114 ohm.m sample (measured at 75 degF) is corrected to a shallower reservoir at 140 degF. What does Arps give?', '["0.0499 ohm.m","0.0635 ohm.m","0.0873 ohm.m","0.114 ohm.m"]'::jsonb, 1, '0.114 x (75 + 6.77)/(140 + 6.77) = 0.114 x 81.77/146.77 = 0.0635 ohm.m. The 0.0873 value belongs to 100 degF and 0.0499 to 180 degF.'),
  ('petrophysics', 'advanced', 'final', null, 10, 'A brine sample is heated. What happens to its resistivity, and why?', '["It falls, because lower viscosity lets the ions move faster and conductivity rises","It rises, because thermal agitation scatters the charge carriers","It is unchanged, because salinity has not changed","It falls only above the boiling point of the brine"]'::jsonb, 0, 'Brine conducts by ionic transport; heating speeds the ions, so conductivity rises and resistivity falls. Hotter formations have lower Rw for the same water.'),
  ('petrophysics', 'advanced', 'final', null, 11, 'A water sample was contaminated with fresher mud filtrate during sampling. What does the Arps correction do about this?', '["It removes the contamination effect as long as the temperatures are entered correctly","It flags the contamination by producing a negative resistivity","Nothing: Arps corrects temperature only, so a compositionally wrong sample stays wrong at every temperature","It partially corrects it, in proportion to the temperature difference"]'::jsonb, 2, 'Arps is a temperature conversion, not a composition fix. Contamination is exactly why the Expert workflow cross-checks with SP and Pickett.'),
  ('petrophysics', 'advanced', 'final', null, 12, 'In the Arps formula Rw2 = Rw1 x (T1 + 6.77)/(T2 + 6.77), what happens when T2 equals T1?', '["The formula is undefined at equal temperatures","The ratio is exactly 1 and the resistivity is unchanged, which is the expected sanity check","The result is Rw1 + 6.77","The result is zero"]'::jsonb, 1, 'Equal temperatures give a ratio of 1: no correction. Checking limiting behaviour is a habit the course applies to every formula.'),
  ('petrophysics', 'advanced', 'final', null, 13, 'The Arps temperature correction is calibrated for which kind of water?', '["Any downhole fluid including oil-base mud filtrates","Distilled water standards used in tool calibration","Potassium-chloride drilling brines only","NaCl-dominated formation brines; other salt systems shift the behaviour"]'::jsonb, 3, 'The 6.77 degF offset linearises NaCl solution behaviour. Unusual brine chemistry or very fresh water needs proper salinity work.'),
  ('petrophysics', 'advanced', 'final', null, 14, 'A bottom-hole temperature is read from a log header recorded shortly after mud circulation stopped. How should this number be treated when it is used as formation temperature?', '["As an underestimate, because circulation cools the borehole and the reading has not recovered to true formation temperature","As an overestimate, because friction from the drill string heats the mud","As exact, because the tool thermometer is calibrated","As unusable in any quantitative work"]'::jsonb, 0, 'Fresh-after-circulation BHTs read low; practice applies Horner-style corrections or uses gradients and test temperatures. Respect where the temperature number comes from.'),
  ('petrophysics', 'advanced', 'final', null, 15, 'Compute the SP temperature coefficient K = 61 + 0.133 x T(degF) at the typewell''s formation temperature of 180 degF.', '["70.98 mV per decade","61.13 mV per decade","84.94 mV per decade","23.94 mV per decade"]'::jsonb, 2, 'K(180) = 61 + 0.133 x 180 = 61 + 23.94 = 84.94 mV per decade of Rmfe/Rwe contrast. The 70.98 value is K at 75 degF.'),
  ('petrophysics', 'advanced', 'final', null, 16, 'The typewell SP quicklook reads SSP = -93 mV with Rmfe = 0.62 ohm.m at 180 degF (K = 84.94). What is Rwe = Rmfe x 10^(SSP/K)?', '["0.62 x 10^(93/84.94) = 7.72 ohm.m","0.62 x 10^(-93/84.94) = 0.0498 ohm.m","0.62 x (93/84.94) = 0.679 ohm.m","0.62 - 93/84.94 = -0.475 ohm.m"]'::jsonb, 1, 'SSP/K = -1.094891, 10 to that power is 0.080373, times 0.62 gives 0.049831 ohm.m. The first distractor drops the sign; the others misuse the formula.'),
  ('petrophysics', 'advanced', 'final', null, 17, 'What physically generates the SP deflection read against a clean permeable bed?', '["Electrochemical potentials: the shale membrane potential plus the liquid-junction potential at the invaded-zone boundary","The tool injecting a survey current into the formation","Induced polarization of clay minerals by the logging cable","Temperature differences between mud and formation"]'::jsonb, 0, 'SP is a natural DC voltage from membrane and liquid-junction potentials; the electrokinetic component is usually minor and the quicklook ignores it.'),
  ('petrophysics', 'advanced', 'final', null, 18, 'With mud filtrate fresher than formation water (Rmf greater than Rw), how does the SP curve behave against a thick clean water sand?', '["It stays on the shale baseline because clean sands generate no SP","It deflects positively, toward higher potential","It oscillates around the baseline","It deflects negatively away from the shale baseline, and the size of the deflection carries the Rmf-to-Rw contrast"]'::jsonb, 3, 'Fresher filtrate against saltier formation water drives a negative SSP in clean permeable beds; that contrast is what makes Rw recoverable from SP.'),
  ('petrophysics', 'advanced', 'final', null, 19, 'At 180 degF (K = 84.94), a clean water sand reads SSP = -84.94 mV, exactly -K. With Rmfe = 0.62 ohm.m, what is Rwe?', '["0.62 ohm.m, because SSP equal to -K means no contrast","0.31 ohm.m, half of Rmfe","0.062 ohm.m, exactly one tenth of Rmfe, because SSP of -K corresponds to one decade of contrast","0.0062 ohm.m, two decades below Rmfe"]'::jsonb, 2, 'K is millivolts per decade: SSP = -K means Rmfe/Rwe = 10, so Rwe = 0.062 ohm.m.'),
  ('petrophysics', 'advanced', 'final', null, 20, 'The engine''s SP chain is labelled a quicklook. Which approximations does it make, and why does it stop there?', '["It assumes the electrokinetic component dominates, because streaming potentials are largest in permeable sands","It treats Rmfe as Rmf and Rw as Rwe, and deliberately omits the full Bateman and Konen equivalent-to-true conversions rather than guess unverified coefficients","It assumes the SP tool reads SSP directly with no bed-thickness effects, which is exact for all bed sizes","It converts SSP with a fixed K of 61 regardless of temperature"]'::jsonb, 1, 'Rmfe ~= Rmf and Rw ~= Rwe hold for moderately saline NaCl waters; the full conversions are left out until a page-referenced source is in hand, the platform''s validation-first rule.'),
  ('petrophysics', 'advanced', 'final', null, 21, 'Suppose the analyst misreads the typewell SSP as -60 mV instead of -93 mV (Rmfe 0.62 ohm.m, K 84.94). What Rwe results, and what is the lesson?', '["0.1219 ohm.m, about 2.4 times the correct value: a 33 mV misread moves Rwe by a large factor, so SSP must be read carefully","0.0498 ohm.m, unchanged, because K absorbs reading errors","0.0322 ohm.m, about 35 percent low","0.62 ohm.m, equal to Rmfe"]'::jsonb, 0, 'Rwe = 0.62 x 10^(-60/84.94) = 0.1219 ohm.m. The exponential form makes Rwe very sensitive to the SSP reading.'),
  ('petrophysics', 'advanced', 'final', null, 22, 'The typewell''s three Rw routes give 0.049910 (Arps lab), 0.049831 (SP quicklook) and 0.0500 ohm.m (Pickett a*Rw with a = 1). What is the correct characterisation of this triangle?', '["The routes disagree by a factor of about 1.5, so more data is needed","Only two routes agree, so the third must be discarded","The agreement is meaningless because all three used the same water leg","The spread is under 0.4 percent of the value, and since the routes fail in different ways the convergence justifies adopting Rw = 0.05 ohm.m"]'::jsonb, 3, 'Lowest to highest spans less than 0.4 percent. Only the Pickett route uses the water leg; the lab and SP routes are independent of it.'),
  ('petrophysics', 'advanced', 'final', null, 23, 'When two Rw routes agree and one disagrees, what does the Expert playbook say?', '["Treat two-against-one as a starting heuristic only: the agreeing pair must also each survive review of their own failure modes before the odd one is set aside","Always adopt the average of all three values","Always trust the lab sample because it is a direct measurement","Discard the outlier immediately and without further work"]'::jsonb, 0, 'Agreement is evidence, not a vote. Each route is checked against its own failure modes, and if nothing reconciles, a documented range goes into sensitivity.'),
  ('petrophysics', 'advanced', 'final', null, 24, 'With the adopted Arps Rw, Archie is run on neutron-density porosity across the typewell water leg (2075-2078 m). The mean Sw comes back 0.9991, essentially the same at all six samples. What does this establish?', '["That the water leg contains residual hydrocarbons","That a validated Rw makes a true water leg read Sw of one within a fraction of a percent, closing the loop on the adopted value","That the neutron-density porosity is biased low in the leg","That the Archie n exponent must be revised upward"]'::jsonb, 1, 'A water leg at Sw = 1 read with the right Rw returns unity; the 0.0009 deficit is just the tiny gap between 0.049910 and the leg''s implied 0.0500.'),
  ('petrophysics', 'advanced', 'final', null, 25, 'Run with the RAW sample value 0.114 ohm.m, the water-leg sample at 2076 m returns Archie Sw = 1.51. The engine reports this value without clamping it to 1. Why?', '["Because the engine has a bug in its saturation routine","Because saturations above 1 are physically possible in transition zones","Because Sw greater than 1 is information: it announces that the parameter set is wrong (here, an uncorrected Rw) before it can corrupt a booking","Because clamping is only applied to porosity, never to saturation"]'::jsonb, 2, 'An impossible Sw in a known water leg is the failure signature of a bad parameter. Silently clamping it to 1 would hide the error.'),
  ('petrophysics', 'advanced', 'final', null, 26, 'The lab route gives a clearly higher Rw than the SP and Pickett routes, which agree with each other. What is the first suspicion?', '["Sample contamination by fresher mud filtrate, or a wrong sample temperature, since the in-situ routes agree and the lab route''s failure modes are exactly these","The Pickett fit used too many points","The SP baseline was drawn on the wrong shale","The formation temperature is wrong in the Arps step, which would also move the SP route"]'::jsonb, 0, 'Lab-route failure modes are contamination and temperature handling. The last distractor is wrong because a bad formation temperature moves BOTH the Arps and SP routes, breaking their agreement.'),
  ('petrophysics', 'advanced', 'final', null, 27, 'Which list correctly states failure modes specific to the Pickett route to Rw?', '["Cycle skipping, washouts and gas effect","Membrane potential suppression and baseline drift","Sample chain-of-custody breaks and bench temperature errors","A water leg that is not truly at Sw = 1, shaliness bending the line, invasion, and the fact that a and Rw arrive as one entangled product"]'::jsonb, 3, 'Pickett stands on the leg being clean, uninvaded and fully water saturated, and it can only ever deliver a*Rw jointly with m.'),
  ('petrophysics', 'advanced', 'final', null, 28, 'Adopting the rounded Rw = 0.05 ohm.m instead of the exact Arps value 0.049910 changes the SAND_A booking how?', '["Net pay drops from 18.0 to 16.5 m","Pay-average Sw jumps from 0.36 to 0.53","Pay-average Sw moves only from 0.3609 to 0.3613 and net pay stays 18.0 m, so the rounding is documented and adopted","The water-leg check fails"]'::jsonb, 2, 'The rounding is far inside the triangulation spread and moves no pay. The large changes in the distractors belong to the RAW 0.114 booking.'),
  ('petrophysics', 'advanced', 'final', null, 29, 'The Expert booking of SAND_A is run twice with the Associate recipe, changing only Rw: corrected 0.049910 gives net 18.0 m, pay-average Sw 0.3609; raw 0.114 gives net 16.5 m, pay-average Sw 0.5303. What is the correct one-line reading of this table?', '["The porosity model is unstable between runs","One uncorrected input inflated every Sw by a factor of about 1.51 and pushed 1.5 m of real pay over the 0.6 Sw cutoff, on identical rock","The two runs used different Vsh transforms, which explains the difference","Net pay is insensitive to Rw because porosity dominates the cutoffs"]'::jsonb, 1, 'Nothing in the rock or the rest of the recipe changed. The Rw error alone moved the booking from 18.0 to 16.5 m net.'),
  ('petrophysics', 'advanced', 'final', null, 30, 'With the Sw cutoff at 0.6 and the raw-to-corrected scaling factor of 1.5113, which samples flip from pay to non-pay when the raw Rw is used?', '["Samples whose corrected Sw lies between 0.6/1.5113 = 0.397 and 0.6","Samples whose corrected Sw lies below 0.397","Samples whose corrected Sw lies above 0.6","All samples in the zone, regardless of saturation"]'::jsonb, 0, 'Scaling by 1.5113 pushes exactly the 0.397-to-0.6 band of corrected saturations above the cutoff; in SAND_A that band holds 1.5 m of section.'),
  ('petrophysics', 'advanced', 'final', null, 31, 'Why does the Expert booking deliberately reuse the Associate-tier recipe (density porosity, Larionov tertiary Vsh, Archie, standard cutoffs) instead of the Professional tier''s methods?', '["Because the Professional methods were shown to be wrong at the Professional tier","Because shaly-sand models cannot be combined with a corrected Rw","To isolate the Rw effect: with porosity, Vsh and cutoffs held fixed, any change in the booking is attributable to Rw alone","Because density porosity is always the most accurate porosity"]'::jsonb, 2, 'It is a controlled experiment: one parameter moves, everything else is pinned, so the sensitivity is cleanly attributed.'),
  ('petrophysics', 'advanced', 'final', null, 32, 'Under the raw-Rw booking of SAND_A, net pay falls from 18.0 to 16.5 m, yet the pay-average porosity RISES slightly (0.2081 to 0.2099). Why?', '["The raw Rw increases the density porosity readings","This is a rounding artefact in the engine","Porosity and saturation are correlated through the Archie equation","The samples that fell out of pay were the poorer ones, so the average over the surviving set rises: conditional averages move when the sample set changes"]'::jsonb, 3, 'Averages taken over a changing pay set can move in unintuitive directions; net and averages must always be read together.'),
  ('petrophysics', 'advanced', 'final', null, 33, 'The corrected-Rw booking of SAND_B (2050-2080 m) gives gross 30.5 m, net 5.5 m, NTG 0.180, pay-average Sw 0.5418. What is the expert reading of this zone?', '["SAND_B is the primary reservoir and SAND_A is upside","A thin oil fringe over the water leg at its base, with transitional saturations near the cutoff, making its booking far more fragile to Rw error than SAND_A''s","A gas cap, indicated by the low NTG","A zone where cutoffs should be abandoned to book more pay"]'::jsonb, 1, 'Low NTG and pay-average Sw near the 0.6 cutoff mean small parameter shifts move a large fraction of SAND_B''s pay; sensitivity matters most where NTG is already low.'),
  ('petrophysics', 'advanced', 'final', null, 34, 'Expressed as hydrocarbon pore thickness (net x pay-average porosity x (1 - pay-average Sw)), the corrected booking gives 18.0 x 0.2081 x 0.6391 = 2.393 m and the raw booking 16.5 x 0.2099 x 0.4697 = 1.626 m. What swing is that?', '["About a 32 percent reduction in hydrocarbon-metres from one uncorrected input","About an 8 percent reduction, roughly the net-pay change alone","No change, because the porosity rise compensates","About a 50 percent increase"]'::jsonb, 0, '1 - 1.626/2.393 = 0.32. The Sw inflation compounds with the lost net, so the volume impact is much larger than the 1.5 m of net alone suggests.'),
  ('petrophysics', 'advanced', 'final', null, 35, 'The corrected-Rw booking (net 18.0 m, Sw 0.3609) reproduces the Associate-tier booking made with the given rw = 0.05 (net 18.0 m, Sw 0.3613). What is the right way to describe this?', '["The Expert work was unnecessary since the answer did not change","A coincidence that should be investigated","The Expert tier earned the answer: the Associate tier assumed 0.05, and the triangulation converted that assumption into evidence","Proof that the raw sample value was also acceptable"]'::jsonb, 2, 'Same number, different epistemic status: a defended parameter instead of a given one. That conversion of assumption into evidence is the whole point of the tier.'),
  ('petrophysics', 'advanced', 'final', null, 36, 'Which six quantities does the Petrophysics Expert capstone grade?', '["Three porosity means, the Pickett fit pair, and SAND_B net pay","The Arps-corrected sample Rw, the SP-quicklook Rwe, the water-leg mean Sw with the Arps Rw, SAND_A net pay with the Arps Rw, SAND_A pay-average Sw with the Arps Rw, and SAND_A net pay with the raw sample value","Rw from six different temperature assumptions","Net, NTG and average Sw for both SAND_A and SAND_B"]'::jsonb, 1, 'Two triangulation routes, the water-leg validation, the corrected booking pair, and the raw-Rw counterfactual net: the six numbers of the Expert workflow.'),
  ('petrophysics', 'advanced', 'final', null, 37, 'The course describes a parameter provenance ladder across the three tiers. Which sequence matches it?', '["Fitted at Associate, given at Professional, triangulated at Expert","Triangulated at Associate, fitted at Professional, given at Expert","Given at every tier, with more decimal places each time","Given at Associate (rw = 0.05 stated), fitted at Professional (a*Rw and m from the Pickett water-leg fit), triangulated at Expert (lab, SP and Pickett convergence)"]'::jsonb, 3, 'Each tier converts one more assumption into evidence: given, then fitted, then triangulated and validated.'),
  ('petrophysics', 'advanced', 'final', null, 38, 'On the deep path, in what order must a learner clear the Expert course''s gates?', '["All module quizzes (75 percent pass each), then the final exam (70 percent), and only then does the capstone unlock","The capstone first, then the final exam as confirmation","The final exam at any time, with module quizzes optional","Any order, as long as everything is passed eventually"]'::jsonb, 0, 'Lessons unlock module quizzes, quizzes unlock the exam, and the exam unlocks the capstone; the server enforces the sequence.'),
  ('petrophysics', 'advanced', 'final', null, 39, 'What does earning the Expert certification trigger commercially?', '["Lifetime free access to the NextGen Academy","An automatic upgrade of the Professional certificate","A personal single-use 50 percent discount code for the corresponding Petrolord Suite module, valid for the certificate''s 12-month window","Nothing beyond the certificate document itself"]'::jsonb, 2, 'The Suite bridge issues the discount code automatically on Expert certification, linking the academy ladder to the professional tools.'),
  ('petrophysics', 'advanced', 'final', null, 40, 'Which statement best captures the course''s definition of a defensible evaluation?', '["One produced by the most senior petrophysicist available","Another expert, given the report and the data, reproduces the numbers and can find no unexamined assumption doing load-bearing work","One where every number is quoted to at least four decimal places","One that matches the pre-drill estimate"]'::jsonb, 1, 'Defensibility is reproducibility plus examined assumptions: provenance, uncertainty and sensitivity for every load-bearing parameter.'),
  ('petrophysics', 'advanced', 'final', null, 41, 'A report quotes SAND_A water saturation as 0.3609 while its Rw came from a single uncorrected lab measurement. What failure does the course name here?', '["Over-rounding: the saturation should carry more decimals","Under-booking: the cutoffs were too strict","Instrument error: the lab meter needs recalibration","False precision: four-decimal output resting on an unexamined single-source input, the exact failure the Expert tier exists to prevent"]'::jsonb, 3, 'Precision in the output means nothing while the input parameter''s provenance is unexamined; the fix is triangulation and sensitivity, not more decimals.'),
  ('petrophysics', 'advanced', 'final', null, 42, 'The typewell deliberately keeps hole conditions ideal. What transfers unchanged from this course to real-field petrophysics?', '["The triangulate, validate and stress-test discipline, the provenance ladder, and the refusal to let one unexamined number drive a booking","The specific values Rw = 0.05 and m = 2, which are universal constants","The assumption that water legs are always present and clean","The exact 0.6 Sw cutoff, mandated for all reservoirs"]'::jsonb, 0, 'Real studies add core, pressure data and advanced logs, but the parameter discipline is the same; the typewell''s ideal conditions exist so that logic stays visible.');
